// ❌ DESAIN BURUK — Tanpa Information Hiding
// Modul lain TAHU detail implementasi database
const user = database.query(`SELECT * FROM users WHERE id = ${id}`);
const hashed = user.password_bcrypt_hash; // Akses langsung ke field internal!

// ✅ DESAIN BAIK — Dengan Information Hiding
// UserRepository menyembunyikan detail SQL dan struktur DB
class UserRepository {
  // Detail implementasi TERSEMBUNYI di dalam class
  #db; // Private field
  #tableName = 'users';

  async findById(id) {
    // Modul lain tidak perlu tahu cara query-nya
    const row = await this.#db.query(
      `SELECT * FROM ${this.#tableName} WHERE id = ?`, [id]
    );
    return this.#mapToUser(row); // Konversi ke domain object
  }

  async verifyPassword(userId, plainPassword) {
    // Logic bcrypt tersembunyi di sini
    const user = await this.findById(userId);
    return bcrypt.compare(plainPassword, user.passwordHash);
  }
}

// Penggunaan dari luar — bersih, tidak bergantung pada detail
const repo = new UserRepository();
const isValid = await repo.verifyPassword(123, 'myPassword');
// Jika DB berubah dari MySQL ke PostgreSQL → hanya ubah di dalam class!
